class DynamicArray<T> {
    private var arr = arrayOfNulls<Any?>(4)
    private var size = 0

    fun add(item: T) {
        if (size == arr.size) {
            arr = arr.copyOf(arr.size * 2) // نتوسّع عند الامتلاء
        }
        arr[size++] = item
    }

    fun get(index: Int): T {
        if (index !in 0 until size) throw IndexOutOfBoundsException()
        @Suppress("UNCHECKED_CAST")
        return arr[index] as T
    }

    fun size() = size
}

fun main() {
    val nums = DynamicArray<Int>()
    for (i in 1..10) nums.add(i)

