fun fibonacci(n: Int): Long {
    // نعالج الحالات الأساسية أولًا
    if (n <= 1) return n.toLong()
    val dp = LongArray(n + 1)
    dp[0] = 0
    dp[1] = 1
    // نملأ الجدول من 2 إلى n
    for (i in 2..n) {
        dp[i] = dp[i - 1] + dp[i - 2]
    }
    return dp[n]
}

