fun minCoinsGreedy(amount: Int, coins: IntArray): List<Int> {
    // نرتب العملات تنازليًا لضمان اختيار الأكبر أولًا
    coins.sortDescending()
    val result = mutableListOf<Int>()
    var remaining = amount
    for (coin in coins) {
        // نستخدم أكبر عدد ممكن من العملة الحالية
        while (remaining >= coin) {
            result.add(coin)
            remaining -= coin
        }
    }
    return result
}

fun main() {
    val coins = intArrayOf(1, 5, 10, 25)
    val amount = 63
    val selected = minCoinsGreedy(amount, coins)
    println("Coins for $amount: ${selected.joinToString()}")
    println("Count: ${selected.size}")
}

