fun main() {
    val weights = intArrayOf(1, 3, 4, 5)
    val values = intArrayOf(1, 4, 5, 7)
    val capacity = 7
    val n = weights.size

    // dp[i][w] = أقصى قيمة باستخدام أول i عناصر وسعة w
    val dp = Array(n + 1) { IntArray(capacity + 1) }

    for (i in 1..n) {
        for (w in 0..capacity) {
            dp[i][w] = dp[i - 1][w]
            if (weights[i - 1] <= w) {
                dp[i][w] = maxOf(dp[i][w], values[i - 1] + dp[i - 1][w - weights[i - 1]])
            }
        }
    }

    println("Maximum value: ${dp[n][capacity]}")
}

fun List<Int>.linearSearch(target: Int): Int {
