class Node(var data: Int, var next: Node? = null)

class LinkedList {
    private var head: Node? = null

    fun insert(data: Int) {
        val newNode = Node(data)
        if (head == null) { head = newNode; return }
        var cur = head
        while (cur?.next != null) cur = cur.next
        cur?.next = newNode
    }

    fun delete(data: Int) {
        if (head == null) return
        if (head?.data == data) { head = head?.next; return }
        var cur = head
        while (cur?.next != null && cur.next?.data != data) cur = cur.next
        if (cur?.next != null) cur.next = cur.next?.next
    }

    fun printList() {
        var cur = head
        while (cur != null) { print("${cur.data} "); cur = cur.next }
        println()
    }
}

fun main() {
    val list = LinkedList()
    list.insert(10); list.insert(20); list.insert(30)
    list.printList()
    list.delete(20)
    list.printList()
}

