fun main() {
    val score = 85
    // لماذا؟ when هنا أنظف من سلسلة if/else الطويلة
    val grade = when {
        score >= 90 -> "A"
        score >= 80 -> "B"
        score >= 70 -> "C"
        else -> "F"
    }
    println("Grade: $grade")

    val day = 3
    val dayName = when (day) {
        1 -> "Monday"
        2 -> "Tuesday"
        3 -> "Wednesday"
        else -> "Unknown"
    }
    println("Day: $dayName")
}

